from pathlib import Path
import json, shutil
from html import escape
C=Path(__file__).resolve().parents[1]/'concepts'
D=Path('/tmp/sh-concepts')
data=json.loads((C/'showcase-ratings.json').read_text())
slugs=['turds','ski','karts','shooter','strategy','lobby','chess']
genres=['Artillery · Multiplayer','Downhill racing','Kart racing · Multiplayer','Third-person shooter','Real-time strategy','Tower tycoon','Chess · Multiplayer']
pitches=['A ridiculous arsenal. A very personal rivalry.','Find your line. Chase the perfect run.','Eight drivers. Sixteen tracks. Beautiful chaos.','The same ridiculous universe. A whole new dimension.','Command the Cold War that never happened.','Build upward. Keep your tower moving.','A quiet club. Your next great opponent.']
games=[]
for i,g in enumerate(data['games']):
 g=dict(g,art='assets/'+slugs[i]+'.webp',genre=genres[i],pitch=pitches[i],rank=i+1,url='https://dashboard.starhermit.com/play/'+g['id'])
 games.append(g)
(C/'product-games.js').write_text('window.SH_GAMES='+json.dumps(games)+';\n')
G='https://dashboard.starhermit.com/'
W='https://wiki.starhermit.com/'
star='<svg viewBox="0 0 32 32" aria-hidden="true"><path d="M16 0l4.2 11.8L32 16l-11.8 4.2L16 32l-4.2-11.8L0 16l11.8-4.2z" fill="currentColor"/><path d="M16 9l1.8 5.2L23 16l-5.2 1.8L16 23l-1.8-5.2L9 16l5.2-1.8z" fill="var(--bg)"/></svg>'
arrow='<span aria-hidden="true">↗</span>'
def signin(label='Sign in & start playing',cls='button primary'):
 return f'<a class="{cls}" href="{G}" target="_blank" rel="noopener">{label}{arrow}</a>'
def publish(label='Add your game',cls='button secondary'):
 return f'<button class="{cls}" data-publish>{label}<span aria-hidden="true">+</span></button>'
def play(g,label='Play now',cls='button primary'):
 return f'<a class="{cls}" href="{g["url"]}" target="_blank" rel="noopener">{label}<span aria-hidden="true">↗</span></a>'
def img(g,cls='',lazy=True):
 return f'<img class="{cls}" src="{g["art"]}" alt="{escape(g["name"])} artwork" width="{1280 if g["rank"]==2 else 1080}" height="{800 if g["rank"]==2 else 1080}"'+(' loading="lazy"' if lazy else ' fetchpriority="high"')+'>'
def score(g):return f'<span class="score"><span aria-hidden="true">★</span> {g["average"]:.1f} <span class="muted">/ 5 · {g["count"]} rating'+('' if g['count']==1 else 's')+'</span></span>'
def nav():return f'<header class="site-header wrap"><a class="brand" href="#">{star}<span>starhermit</span></a><nav aria-label="Main navigation"><a href="#games">Discover games</a><a href="#creators">For creators</a><a href="#community">Community</a></nav><div class="nav-actions">{publish("Add a game","nav-publish")}{signin("Sign in","button nav-signin")}</div></header>'
def browser():
 tiles=''.join(f'<a class="mini-game" href="{g["url"]}" target="_blank" rel="noopener">{img(g,lazy=False)}<span><b>{escape(g["name"])}</b>{score(g)}</span><span class="mini-play" aria-label="Play">↗</span></a>' for g in games[:3])
 return f'''<div class="product-window"><div class="window-top"><span>{star} Your next favorite</span><span class="window-dots">● ● ●</span></div><div class="product-body"><div class="product-switch" role="group" aria-label="Preview mode"><button data-product-mode="play" aria-pressed="true">For players</button><button data-product-mode="create" aria-pressed="false">For creators</button></div><div data-product-panel="play"><div class="product-heading"><span>Good games.<br>Better company.</span><small>HIGHEST RATED</small></div><div class="mini-grid">{tiles}</div><div class="product-bottom"><span>One account.<br><b>A whole world of games.</b></span>{signin('Get started','button primary compact')}</div></div><div data-product-panel="create" hidden><div class="product-heading"><span>Your game.<br>Your next chapter.</span><small>START HERE</small></div><div class="preview-methods"><span>01 <b>Add a repository or build</b></span><span>02 <b>Give your game a home</b></span><span>03 <b>Invite your first players</b></span></div>{publish('Start with your game','button primary')}</div></div></div>'''
def service_mesh():
 return f'''<div class="mesh" aria-label="StarHermit connects your game to hosting, players, saves and community"><div class="mesh-orbit orbit-one"></div><div class="mesh-orbit orbit-two"></div><div class="mesh-core">{star}<b>Your game</b><small>POWERED BY STARHERMIT</small></div><div class="mesh-node node-host"><span class="node-icon">↗</span><b>Game hosting</b><small>A place to launch</small></div><div class="mesh-node node-players"><span class="node-icon">◎</span><b>Matchmaking</b><small>Find the next match</small></div><div class="mesh-node node-saves"><span class="node-icon">◫</span><b>Player progress</b><small>Scores. Saves. Milestones.</small></div><div class="mesh-node node-social"><span class="node-icon">✳</span><b>Community</b><small>Friends. Chat. Voice.</small></div><div class="mesh-label">BUILD THE GAME. WE CONNECT THE REST.</div></div>'''
def deploy_board():
 return f'''<div class="deploy-board"><div class="deploy-top"><span>{star} From build to community</span><span class="small-label">YOUR NEXT RELEASE</span></div><div class="deploy-source"><span class="code-icon">⌘</span><div><b>Bring your game</b><span>Repository, local build or server image</span></div><button data-publish aria-label="Choose your game source">+</button></div><div class="deploy-track"><i></i><span>01 &nbsp; Add your project</span><i></i><span>02 &nbsp; Deploy on StarHermit</span><i></i><span>03 &nbsp; Share it with players</span></div><div class="deploy-services"><span>↗ <b>Hosting</b></span><span>◎ <b>Multiplayer</b></span><span>◫ <b>Player state</b></span><span>✳ <b>Community</b></span></div><div class="deploy-cta"><span>Your next game<br><b>belongs here.</b></span>{publish('Let’s launch','button primary compact')}</div></div>'''
def spotlight():
 g=games[0]
 return f'''<div class="spotlight-art">{img(g,lazy=False)}<div class="spotlight-top"><span class="pill">#1 PLAYER RATED</span><span class="spotlight-orbit">{star}</span></div><div class="spotlight-bottom"><span>{g['genre']}</span><h2>{g['name']}</h2><div>{score(g)}{play(g,'Sign in to play','button white compact')}</div></div></div><div class="spotlight-note"><span class="live-dot"></span> A real game. Ready when you are.</div>'''
def cards_section(mode):
 cards=''.join(f'''<article class="game-card" data-game-category="{'multiplayer' if g['rank'] in (1,3,4,7) else 'solo'}"><a class="game-image" href="{g['url']}" target="_blank" rel="noopener">{img(g)}<span class="game-rank">{g['rank']:02d}</span><span class="image-play">Play {arrow}</span></a><div class="game-details"><small>{g['genre']}</small><h3><a href="{g['url']}" target="_blank" rel="noopener">{escape(g['name'])}</a></h3>{score(g)}<p>{g['pitch']}</p>{play(g,'Sign in to play','text-link')}</div></article>''' for g in games[:5])
 return f'''<section class="games-section wrap" id="games"><div class="section-head"><div><span class="eyebrow">CREATOR-MADE. PLAYER-LOVED.</span><h2>Start with a great game.</h2></div><div><p>The highest-rated games on StarHermit.<br>Pick one. Sign in. You’re in.</p><a class="text-link" href="{G}" target="_blank" rel="noopener">Explore the library {arrow}</a></div></div><div class="game-tools"><div class="filters" role="group" aria-label="Filter games"><button data-filter="all" aria-pressed="true">All favorites</button><button data-filter="multiplayer" aria-pressed="false">Play together</button><button data-filter="solo" aria-pressed="false">A little solo time</button></div><span>Player ratings · 08 Oct 2026</span></div><div class="games-grid">{cards}</div><p class="rating-note">Ranked by average rating, then rating count. Ratings shown with their sample sizes.</p></section>'''
def creators():
 return f'''<section class="creator-section wrap" id="creators"><div class="creator-copy"><span class="eyebrow">FOR THE PEOPLE MAKING GAMES</span><h2>You make the game.<br><em>We make room for it.</em></h2><p>Put your game online, give players a way in, and build the community around it. Start with a GitHub repository, a local build or a dedicated server image.</p><div class="cta-row">{publish('Add your game','button primary')}<a href="{W}" target="_blank" rel="noopener" class="text-link">Explore the docs {arrow}</a></div><small class="creator-hint">Sign in, choose Add Game, and bring your project.</small></div><div class="creator-steps"><div><span>01</span><section><h3>Bring what you’ve built.</h3><p>Connect a repository or upload a build. Your work gets its own place on the platform.</p></section></div><div><span>02</span><section><h3>Give it the infrastructure.</h3><p>Hosting, matchmaking, player state, leaderboards and achievements, ready to integrate.</p></section></div><div><span>03</span><section><h3>Give people a reason to return.</h3><p>Friends, invitations, chat and voice bring your players together around your game.</p></section></div></div></section>'''
def infra():
 services=[('↗','A home for your game','Publish browser games from a repository or a local build.'),('◎','A way to play together','Connect players with matchmaking and multiplayer sessions.'),('◫','Progress that stays with you','Integrate player state, leaderboards and achievements.'),('✳','People, already connected','Friends, game invitations, chat and voice in one platform.')]
 return '<section class="infra-section wrap"><div class="section-head"><div><span class="eyebrow">THE PLATFORM BEHIND THE PLAY</span><h2>More than a place to upload.</h2></div><p>Build on the infrastructure.<br>Grow with the community.</p></div><div class="infra-grid">'+''.join(f'<article><span class="infra-icon">{icon}</span><h3>{title}</h3><p>{copy}</p></article>' for icon,title,copy in services)+'</div></section>'
def community():
 return f'''<section class="community-section wrap" id="community"><div class="community-graphic" aria-hidden="true"><span class="community-center">{star}</span><span class="community-icon c-one">✳</span><span class="community-icon c-two">↗</span><span class="community-icon c-three">◎</span><span class="community-icon c-four">+</span><svg viewBox="0 0 460 260"><path d="M230 130L90 65M230 130L350 50M230 130L370 200M230 130L110 205"/></svg></div><div><span class="eyebrow">GOOD GAMES BRING PEOPLE TOGETHER</span><h2>Find your people.<br>Bring your next game.</h2><p>Your account connects your games, your progress and your friends. Join a match, send an invitation, or gather in chat and voice.</p>{signin('Join StarHermit','button primary')}</div></section>'''
def closing():return f'''<section class="closing wrap"><span class="eyebrow">PLAYER. CREATOR. BOTH.</span><h2>There’s a place for you here.</h2><div class="cta-row">{signin('Sign in & get started')}{publish()}</div><p>Choose your preferred sign-in provider to get started. Play browser games without installing a client.</p></section><footer class="site-footer wrap"><a class="brand" href="#">{star}<span>starhermit</span></a><span>A platform for games and the people behind them.</span><div><a href="{G}" target="_blank" rel="noopener">Sign in</a><a href="{W}" target="_blank" rel="noopener">Developer docs</a><a href="https://starhermit.com/privacy.html" target="_blank" rel="noopener">Privacy</a></div></footer>'''
def dialog():
 return f'''<dialog class="publish-dialog" aria-labelledby="publish-title"><button class="dialog-close" data-close-publish aria-label="Close publishing guide">×</button><span class="eyebrow">YOUR GAME’S NEXT CHAPTER</span><h2 id="publish-title">Let’s get your game<br>onto StarHermit.</h2><p>How would you like to bring it?</p><div class="source-choices" role="group" aria-label="Game source"><button data-source="repository" aria-pressed="true"><b>⌘ &nbsp; GitHub repository</b><span>Start with your source code</span></button><button data-source="folder" aria-pressed="false"><b>◫ &nbsp; Local build</b><span>Upload a game from your computer</span></button><button data-source="server" aria-pressed="false"><b>◎ &nbsp; Server image</b><span>Bring a dedicated game server</span></button></div><div class="source-guide" aria-live="polite"><b data-source-heading>Have your repository URL ready.</b><p data-source-copy>After signing in, select Add Game in the dashboard and paste your GitHub repository URL.</p></div>{signin('Sign in to add your game','button primary')}<small>Sign-in creates your account. You’ll add your project in the dashboard.</small></dialog>'''
concepts=[
 ('platform','01','Open Platform','Clear, confident and product-led. Equal space for players and creators.','Games deserve<br>a place to <em>grow.</em>','Play something great. Put your own game online. Find your people. The infrastructure and community are already here.','A HOME FOR YOUR NEXT GAME','browser'),
 ('playground','02','After Hours','A premium game destination that makes the first play feel immediate.','Your next<br>great game<br><em>starts here.</em>','Discover games made by independent creators. Sign in, play together, and make a little room for your own.','CREATOR-MADE. PLAYER-LOVED.','spotlight'),
 ('workshop','03','Creator Studio','A creator-first platform, with publishing as the shortest path into the product.','Built by you.<br><em>Played by everyone.</em>','Bring your game. We bring hosting, multiplayer infrastructure and a community ready to discover what you’ve made.','MAKE SOMETHING WORTH PLAYING','deploy'),
 ('network','04','Connected Worlds','A precise, technical direction that makes the platform’s infrastructure tangible.','The game is yours.<br><em>The platform<br>is here.</em>','Publish your game into a connected world of players, friends and shared infrastructure. Or find a new world to play in.','GAMES. INFRASTRUCTURE. COMMUNITY.','mesh'),
 ('collective','05','The Collective','A warmer independent-games identity, with playful but disciplined art direction.','Good games.<br>Good people.<br><em>Your kind of place.</em>','A home for independent games and the people making them. Find something to play. Share something you’ve built.','COME FOR A GAME. STAY FOR THE PEOPLE.','collective')]
for slug,num,name,desc,title,copy,kicker,visual in concepts:
 if visual=='browser': art=browser()
 elif visual=='spotlight':art=spotlight()
 elif visual=='deploy':art=deploy_board()
 elif visual=='mesh':art=service_mesh()
 else: art=f'<div class="collective-art"><div class="collective-main">{img(games[0],lazy=False)}<span>{score(games[0])}<b>Turds</b>{play(games[0],"Let’s play","button white compact")}</span></div><div class="collective-small">{img(games[2],lazy=False)}<span>Turd Karts {arrow}</span></div><div class="collective-stamp">{star}<span>INDEPENDENT<br>BY NATURE.</span></div><button class="collective-add" data-publish>YOUR GAME<br><b>GOES HERE +</b></button></div>'
 heroactions=(publish('Add your game','button primary')+signin('Sign in to play','button secondary')) if slug in ('workshop','network') else signin()+publish()
 hero=f'''<section class="hero wrap"><div class="hero-copy"><span class="eyebrow"><i class="live-dot"></i>{kicker}</span><h1>{title}</h1><p>{copy}</p><div class="cta-row">{heroactions}</div><div class="hero-note"><span>✓</span> One account. Your games, your people.</div><a class="hero-scroll" href="#games">Meet your next favorite <span>↓</span></a></div><div class="hero-visual"><canvas class="platform-canvas" data-scene="{slug}" aria-hidden="true"></canvas>{art}</div></section>'''
 belt='<div class="value-belt wrap"><span>A PLACE TO PLAY</span><i>✦</i><span>A PLATFORM TO BUILD ON</span><i>✦</i><span>A COMMUNITY TO GROW WITH</span></div>'
 sections=creators()+infra()+cards_section(slug) if slug in ('workshop','network') else cards_section(slug)+creators()+infra()
 html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex"><title>StarHermit — {name} concept</title><link rel="icon" href="data:,"><link rel="preload" href="fonts/inter.ttf" as="font" type="font/ttf" crossorigin><link rel="stylesheet" href="product.css"><script src="product-games.js" defer></script><script src="product.js" defer></script><script src="platform-gl.js" defer></script></head><body class="theme-{slug}"><a class="skip-link" href="#main">Skip to content</a>{nav()}<main id="main">{hero}{belt}{sections}{community()}{closing()}</main>{dialog()}<div class="concept-label"><a href="index.html" target="_top">← All concepts</a><span>{num} / {name}</span></div></body></html>'''
 (C/(slug+'.html')).write_text(html)
(C/'product-directions.json').write_text(json.dumps([dict(slug=c[0],number=c[1],name=c[2],description=c[3]) for c in concepts],indent=2))

# The CSS and browser scripts are maintained alongside the generated HTML.
D.mkdir(exist_ok=True)
for name in ['platform','playground','workshop','network','collective']:
 shutil.copy2(C/(name+'.html'), D/(name+'.html'))
for name in ['product-games.js','product-directions.json','showcase-ratings.json']:
 shutil.copy2(C/name,D/name)
